import{_ as i,C as n,o as t,c as o,a2 as a,b as l,w as s,a as d,E as p,a3 as c}from"./chunks/framework.CZqXuAiL.js";const f=JSON.parse('{"title":"Pterodactyl Revamp","description":"Enterprise operations layer for Pterodactyl Panel — bulk server operations, multi-server creation, tagging, templates, metrics, health scoring, global search, and audit logging.","frontmatter":{"title":"Pterodactyl Revamp","description":"Enterprise operations layer for Pterodactyl Panel — bulk server operations, multi-server creation, tagging, templates, metrics, health scoring, global search, and audit logging."},"headers":[],"relativePath":"pterodactyl-revamp/index.md","filePath":"pterodactyl-revamp/index.md","lastUpdated":1785589481000}'),h={name:"pterodactyl-revamp/index.md"};function u(g,e,m,v,k,b){const r=n("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="pterodactyl-revamp" tabindex="-1">Pterodactyl Revamp <a class="header-anchor" href="#pterodactyl-revamp" aria-label="Permalink to &quot;Pterodactyl Revamp&quot;">​</a></h1><p>Pterodactyl Revamp is an enterprise operations layer for <strong>Pterodactyl Panel 1.12.x – 1.14.x</strong> that adds bulk server operations, multi-server creation, tagging, templates, metrics, health scoring, global search, and audit logging on top of the stock admin panel.</p><div class="info custom-block"><p class="custom-block-title">Version</p><p>Current release: <strong>1.2.0</strong> · Blueprint target: <code>beta-2026-06</code> · <a href="https://github.com/AnAverageBeing/pterodactyl-revamp" target="_blank" rel="noreferrer">GitHub repository</a></p></div><h2 id="key-features" tabindex="-1">Key features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key features&quot;">​</a></h2><ul><li><strong>Bulk operations</strong> — run power actions, rebuilds, suspensions, and moves across many servers at once, with preflight validation and per-item status tracking</li><li><strong>Multi-server create</strong> — provision batches of servers from one form, with naming-pattern previews</li><li><strong>Server tagging</strong> — organize servers with tags and filter the admin server list by them</li><li><strong>Server templates</strong> — reusable creation templates with revision history</li><li><strong>Allocation port picker</strong> — an improved allocation UX for choosing ports during server creation</li><li><strong>Metrics and analytics</strong> — scheduled metric sampling with hourly rollups and dashboard charts</li><li><strong>Health scoring</strong> — node and server health snapshots with computed scores and recommendations</li><li><strong>Global search</strong> — search across servers, nodes, and users from the admin area</li><li><strong>Audit log</strong> — an admin audit trail of every action Revamp performs</li><li><strong>Admin dashboard</strong> — a dedicated operations dashboard at <code>/admin/revamp</code></li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>Revamp runs entirely inside the panel: Blade views with jQuery islands (plus an optional React bundle) talk to Revamp&#39;s own admin controllers, which delegate to service classes that wrap core Pterodactyl services and Wings. Metrics sampling, health scoring, and bulk jobs run through the queue and scheduler.</p>',7)),(t(),l(c,null,{default:s(()=>[p(r,{id:"mermaid-72",class:"mermaid",graph:"graph%20TD%0A%20%20A%5BAdmin%20browser%5D%20--%3E%20B%5BBlade%20views%20%2B%20jQuery%20islands%5D%0A%20%20A%20--%3E%20R%5BOptional%20React%20bundle%5D%0A%20%20B%20--%3E%20C%5BRevamp%20admin%20controllers%3Cbr%2F%3E%2Fadmin%2Frevamp%5D%0A%20%20R%20--%3E%20C%0A%20%20C%20--%3E%20S%5BRevamp%20services%3Cbr%2F%3EBulkOps%20%C2%B7%20Tags%20%C2%B7%20Templates%20%C2%B7%3Cbr%2F%3EMetrics%20%C2%B7%20Health%20%C2%B7%20Search%20%C2%B7%20Audit%5D%0A%20%20S%20--%3E%20P%5BCore%20Pterodactyl%20services%5D%0A%20%20S%20--%3E%20W%5BWings%20daemon%5D%0A%20%20Q%5BQueue%20worker%3Cbr%2F%3Equeue%3Drevamp%2Cdefault%5D%20--%3E%20S%0A%20%20CRON%5BScheduler%3Cbr%2F%3Eartisan%20schedule%3Arun%5D%20--%3E%20S%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="quick-install" tabindex="-1">Quick install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick install&quot;">​</a></h2><p>With Blueprint installed on your panel:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Background workers required</p><p>Revamp expects a queue worker and the scheduler to be running, or metrics, health scoring, and bulk jobs will never execute:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=revamp,default</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> php /var/www/pterodactyl/artisan schedule:run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /dev/null </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">2&gt;&amp;1</span></span></code></pre></div></div><h2 id="install-paths" tabindex="-1">Install paths <a class="header-anchor" href="#install-paths" aria-label="Permalink to &quot;Install paths&quot;">​</a></h2><p>Revamp ships in two flavors. Pick the one that matches how you manage your panel.</p><table tabindex="0"><thead><tr><th></th><th>Blueprint extension</th><th>Standalone merge</th></tr></thead><tbody><tr><td><strong>How it installs</strong></td><td><code>blueprint -i pterodactylrevamp</code> runs <code>data/install.sh</code>, which merges PanelFiles and patches admin blades automatically</td><td>Copy <code>standalone/PanelFiles/</code> into the panel manually (or via ainx, etc.)</td></tr><tr><td><strong>Best for</strong></td><td>Panels already managed by Blueprint</td><td>Panels without Blueprint, or fully manual control</td></tr><tr><td><strong>Removal</strong></td><td><code>blueprint -remove pterodactylrevamp</code> restores the vanilla blades</td><td>Manual — restore from the included <code>data/vanilla/</code> copies</td></tr><tr><td><strong>Updates</strong></td><td>Reinstall through Blueprint</td><td>Re-merge PanelFiles on top of the panel</td></tr></tbody></table><p>See <a href="/pingless-studios-docs/pterodactyl-revamp/getting-started/installation">Installation</a> for the full walkthrough of both paths.</p><div class="tip custom-block"><p class="custom-block-title">Requirements</p><p>PHP <strong>8.2 / 8.3</strong>, MySQL/MariaDB <strong>10.4+</strong>, and a Pterodactyl panel on <strong>1.12.x – 1.14.x</strong>.</p></div><div class="danger custom-block"><p class="custom-block-title">Bulk move is opt-in</p><p>Bulk move only re-points panel database records — it does <strong>not</strong> transfer server data through Wings, which would leave servers broken. It is gated behind the <code>bulk_move_enabled</code> setting (default <strong>off</strong>). Enable it only if you understand the consequences. See <a href="/pingless-studios-docs/pterodactyl-revamp/configuration/reference">Configuration</a>.</p></div><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="/pingless-studios-docs/pterodactyl-revamp/getting-started/installation">Installation</a></td><td>Both install paths, requirements, queue worker, and cron setup</td></tr><tr><td><a href="/pingless-studios-docs/pterodactyl-revamp/configuration/reference">Configuration</a></td><td>Every Revamp setting, including <code>bulk_move_enabled</code></td></tr><tr><td><a href="/pingless-studios-docs/pterodactyl-revamp/user-guide/cli">CLI</a></td><td>Artisan commands for metrics sampling, rollups, health, and rule evaluation</td></tr><tr><td><a href="/pingless-studios-docs/pterodactyl-revamp/user-guide/api">API</a></td><td>Application API endpoints exposed by Revamp</td></tr><tr><td><a href="/pingless-studios-docs/pterodactyl-revamp/architecture/overview">Architecture</a></td><td>Controllers, services, jobs, and database tables in depth</td></tr></tbody></table>',12))])}const B=i(h,[["render",u]]);export{f as __pageData,B as default};
